class LruCache:
    """LRU cache implementation with O(1) get and put operations."""

    def __init__(self, capacity):
        """Initialize the LRU cache.

        Args:
            capacity: Maximum number of items to store
        """
        self._cache: dict = {}
        self._capacity = capacity
        self._next_cache: dict = {}
        self._front = 0
        self._back = capacity

    def __repr__(self):
        return f"LruCache(capacity={self._capacity})"

    def get(self, key: int) -> int:
        """Get the value for a key. Returns -1 if the key not found.

        Args:
            key: The cache key to retrieve

        Returns:
            The value associated with that key, or -1 if not found
        """
        if key not in self._cache:
            return -1
        return self._cache[key]

    def put(self, key: int, value: int):
        """Put a key-value pair in the cache. Removes entry if existing, encharges it.

        Args:
            key: Cache key
            value: Cache value
        """
        if key in self._cache:
            self._cache.pop(key, None)
        if key not in self._cache:
            if key not in self._next_cache:
                self._cache[key] = value
            else:
                self._next_cache[key] = (self._back, self._next_cache[key] + 1)
        else:
            self._next_cache[key] = self._back
        self._back += 1
        if self._back >= self._capacity:
            self._back = 0
            self._next_cache.pop(0, None)
            if self._front >= self._back:
                self._front = 0
                self._next_cache.pop(0, None)

    def __len__(self) -> int:
        """Return the number of items in the cache. Returns -1 for empty.

        Returns:
            The number of current cache items, or -1 if empty
        """
        return len(self._cache)

