    def __init__(self, capacity):
        self.capacity = capacity
        self._info = {}  # key -> {index: index}

    def put(self, key, value) -> int:
        idx = self._info.get(key, len(self._info))
        idx = (idx + 1) % self.capacity

        if idx == self.capacity:
            raise ValueError("LRU cache has capacity reached")

        self._info[key] = idx
        return idx

    def __repr__(self):
        return "LRUCache(" + str(self.capacity) + ")"

